const $=id=>document.getElementById(id);let cards=[],selected=null,next=null,busy=false;let saved=[];try{saved=JSON.parse(localStorage.getItem('mana-saved')||'[]');if(!Array.isArray(saved))saved=[]}catch{}const stores=['CardTrader','Star City Games','Cardmarket','Card Kingdom'];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(n);function status(s){$('status').textContent=s}function cardImage(c){return c.image_uris?.normal||c.card_faces?.[0]?.image_uris?.normal||''}function storeLink(i){const n=encodeURIComponent(selected.name);return i===3?'https://www.cardkingdom.com/catalog/search?search=header&filter%5Bname%5D='+n:i===0?'https://www.cardtrader.com/en/cards?search='+n:i===1?'https://starcitygames.com/search/?search_query='+n:selected.purchase_uris?.cardmarket||'https://www.cardmarket.com/en/Magic/Products/Search?searchString='+n}async function search(url,append=false){if(busy)return;busy=true;$('searchBtn').disabled=true;$('more').disabled=true;status('Buscando ediciones en Scryfall…');try{const r=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw new Error(r.status===404?'No encontramos esa carta. Prueba su nombre en inglés.':'El catálogo no está disponible. Intenta de nuevo en unos momentos.');const data=await r.json();cards=append?cards.concat(data.data):data.data;next=data.has_more?data.next_page:null;renderResults();status(`${cards.length} ediciones cargadas. Selecciona la impresión exacta.`)}catch(e){status(e.name==='TimeoutError'?'La búsqueda tardó demasiado. Vuelve a intentarlo.':e.message||'No se pudo conectar al catálogo.')}finally{busy=false;$('searchBtn').disabled=false;$('more').disabled=false}}
function renderResults(){$('results').innerHTML=cards.map((c,i)=>`<button class="result" data-index="${i}">${cardImage(c)?`<img src="${esc(cardImage(c))}" alt="${esc(c.name)}" loading="lazy">`:''}<strong>${esc(c.name)}</strong><small>${esc(c.set_name)} · #${esc(c.collector_number)}<br>${esc(c.lang.toUpperCase())} · ${esc(c.finishes.join(' / '))}</small></button>`).join('');$('more').hidden=!next}
$('search').onsubmit=e=>{e.preventDefault();const q=$('query').value.trim();if(q){$('results').innerHTML='';$('more').hidden=true;search('https://api.scryfall.com/cards/search?unique=prints&order=released&q='+encodeURIComponent('game:paper name:"'+q.replace(/["\\]/g,'')+'"'))}};document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{$('query').value=b.dataset.query;$('search').requestSubmit()});$('more').onclick=()=>{if(next)search(next,true)};$('results').onclick=e=>{const b=e.target.closest('[data-index]');if(b)select(cards[+b.dataset.index])};
function select(c,record){selected=c;$('compare').hidden=false;$('cardName').textContent=c.name;$('edition').textContent=`${c.set_name} · ${c.set.toUpperCase()} · #${c.collector_number}`;$('cardImg').src=cardImage(c);$('cardImg').alt=c.name;$('finish').innerHTML=c.finishes.map(f=>`<option>${esc(f)}</option>`).join('');$('offers').innerHTML=stores.map((s,i)=>`<div class="offer"><div><h3>${s}</h3><a href="${esc(storeLink(i))}" target="_blank" rel="noopener noreferrer">${i===2?'Ver edición':'Buscar en tienda'} ↗</a></div><label>${i===0?'Precio de compra':'Venta de referencia'}<input id="p${i}" type="number" min="0" step="any" placeholder="Sin precio"></label><label>Moneda<select id="c${i}"><option>USD</option><option ${i===2?'selected':''}>EUR</option><option>MXN</option></select></label><label>Envío (opcional)<input id="s${i}" type="number" min="0" step="any" placeholder="No incluido"></label>${i===1||i===3?`<label class="stockfield">Existencias verificadas por ti<select id="stock${i}"><option value="unknown">Sin verificar</option><option value="in_stock">Con existencias</option><option value="out_of_stock">Agotado</option></select></label>`:''}</div>`).join('');if(record){$('language').value=record.language;$('condition').value=record.condition;$('finish').value=record.finish;$('usd').value=record.usd;$('eur').value=record.eur;record.offers.forEach((o,i)=>{$('p'+i).value=o.price;$('c'+i).value=o.currency;$('s'+i).value=o.shipping;if($('stock'+i))$('stock'+i).value=o.stock||'unknown'})}else{const langs={en:'English',es:'Español',ja:'Japonés'};$('language').value=langs[c.lang]||'English'}$('cmLink').href=storeLink(2);reference();calculate();$('compare').scrollIntoView({behavior:'smooth',block:'start'})}
function reference(){const f=$('finish').value;const p=f==='nonfoil'?selected.prices?.eur:f==='foil'?selected.prices?.eur_foil:null;$('reference').textContent=p?`Referencia Cardmarket vía Scryfall: €${p}. No es una oferta verificada para el idioma y condición elegidos. Consultada: ${new Date().toLocaleDateString('es-MX')}. La fuente no indica aquí la hora de actualización.`:'Sin precio de referencia para este acabado. Puedes ingresar una oferta manual.'}
function totals(){return stores.map((name,i)=>{const raw=$('p'+i).value;const price=Number(raw),shipping=Number($('s'+i).value||0),currency=$('c'+i).value;const rate=currency==='MXN'?1:Number($(currency==='USD'?'usd':'eur').value);return{name,missing:raw==='',valid:raw!==''&&Number.isFinite(price)&&price>=0&&Number.isFinite(shipping)&&shipping>=0&&Number.isFinite(rate)&&rate>0,total:(price+shipping)*rate,hasShipping:$('s'+i).value!==''}})}
function calculate(){
 if(!selected)return;
 const all=totals(),buy=all[0];
 if(!buy.valid){$('winner').textContent='Ingresa el precio de compra en CardTrader y un tipo de cambio válido para calcular tu posible ganancia.';return}
 if(buy.total<=0){$('winner').textContent='El costo de compra en CardTrader debe ser mayor que cero para calcular el porcentaje de ganancia.';return}
 const candidates=[1,3].map(i=>({name:stores[i],stock:$('stock'+i).value,price:all[i].valid?Number($('p'+i).value)*( $('c'+i).value==='MXN'?1:Number($($('c'+i).value==='USD'?'usd':'eur').value)):NaN}));
 const chosen=chooseRetailReference(candidates);
 let primary='<p>No hay un precio público válido con existencias confirmadas en Star City Games o Card Kingdom. Verifica precio y disponibilidad.</p>';
 if(chosen){const p=profitFromPurchase(buy.total,chosen.price);primary=`<div class="profit ${p.amount<0?'loss':''}"><h3>Referencia elegida: ${esc(chosen.name)}</h3><strong>${p.percent>0?'+':''}${p.percent.toFixed(1)}%</strong><p>${p.amount<0?'Pérdida':'Ganancia'} potencial bruta: <b>${money(p.amount)} MXN</b></p><p>Precio público: ${money(chosen.price)} MXN</p><small>${candidates.every(c=>c.stock==='in_stock'&&Number.isFinite(c.price)&&c.price>0)?'Es el precio público más alto entre ambas tiendas con existencias.':'Es la referencia con precio y existencias confirmados; la otra está agotada o pendiente de verificar.'}</small></div>`}
 const rows=all.slice(1).map((o,j)=>{
  if((j===0||j===2)&&$('stock'+(j+1)).value!=='in_stock')return `<article class="profit"><h3>${esc(o.name)}</h3><p>${$('stock'+(j+1)).value==='out_of_stock'?'Agotado · excluido del cálculo':'Existencias sin verificar · excluido del cálculo'}</p></article>`;
  if(o.missing)return `<article class="profit"><h3>${esc(o.name)}</h3><p>Agrega el precio de venta de referencia.</p></article>`;
  if(!o.valid)return `<article class="profit"><h3>${esc(o.name)}</h3><p>Revisa el precio, envío y tipo de cambio.</p></article>`;
  const i=j+1,currency=$('c'+i).value,rate=currency==='MXN'?1:Number($(currency==='USD'?'usd':'eur').value);
  const sale=Number($('p'+i).value)*rate;
  const result=profitFromPurchase(buy.total,sale);
  const sign=result.amount>0?'+':'';
  return `<article class="profit ${result.amount<0?'loss':''}"><h3>Frente a ${esc(o.name)}</h3><strong>${sign}${result.percent.toFixed(1)}%</strong><p>${result.amount<0?'Pérdida potencial':result.amount===0?'Sin ganancia':'Ganancia potencial bruta'}: <b>${money(result.amount)} MXN</b></p><small>Venta hipotética: ${money(sale)} MXN · Precio de carta sin envío.</small></article>`;
 });
 $('winner').innerHTML=`<div class="eyebrow">COMPRANDO EN CARDTRADER</div><h3>Costo de compra: ${money(buy.total)} MXN</h3><p class="hint">${buy.hasShipping?'Incluye el envío de compra indicado.':'No incluye envío de compra: agrégalo para mejorar la estimación.'}</p><div class="primaryprofit">${primary}</div><p class="hint">Selección automática entre Star City y Card Kingdom con los precios y existencias ingresados. Cardmarket se muestra aparte y no interviene en esta selección.</p><div class="profitgrid">${rows.join('')}</div><p class="hint">Ganancia sobre costo (%) = (precio de venta de referencia − costo de compra) ÷ costo de compra × 100. No es margen sobre venta. Los precios de tienda no son ofertas de recompra ni garantizan que vendas a ese precio. No se descuentan comisiones, impuestos ni envío de reventa.</p>`;
}
$('compare').addEventListener('input',calculate);$('finish').onchange=()=>{reference();clearPrices()};function clearPrices(){stores.forEach((_,i)=>{$('p'+i).value='';$('s'+i).value='';if($('stock'+i))$('stock'+i).value='unknown'});calculate()}$('language').onchange=clearPrices;$('condition').onchange=clearPrices;
function sync(){try{localStorage.setItem('mana-saved',JSON.stringify(saved));$('count').textContent=saved.length;return true}catch{status('No fue posible guardar: el almacenamiento de este navegador no está disponible.');return false}}$('count').textContent=saved.length;
$('save').onclick=()=>{if(!selected)return;const checked=totals();if(!checked[0].valid||checked[0].total<=0||!checked.slice(1).some(o=>o.valid)){status('Agrega un costo positivo de CardTrader y un precio de referencia válido antes de guardar.');return}const record={id:crypto.randomUUID(),card:selected,language:$('language').value,condition:$('condition').value,finish:$('finish').value,usd:$('usd').value,eur:$('eur').value,offers:stores.map((_,i)=>({price:$('p'+i).value,currency:$('c'+i).value,shipping:$('s'+i).value,stock:$('stock'+i)?.value||'unknown'})),date:new Date().toISOString()};saved.unshift(record);if(sync()){status('Comparación guardada en este navegador.');$('save').textContent='✓ Comparación guardada';setTimeout(()=>$('save').textContent='☆ Guardar comparación',1800)}else saved.shift();renderSaved()};function renderSaved(){$('savedList').innerHTML=saved.length?saved.map(r=>`<div class="savedrow"><div><strong>${esc(r.card.name)}</strong><small>${esc(r.card.set_name)} · #${esc(r.card.collector_number)} · ${esc(r.finish)} · ${new Date(r.date).toLocaleDateString('es-MX')}</small></div><button data-open="${esc(r.id)}" class="quiet">Abrir</button><button data-delete="${esc(r.id)}" class="quiet" aria-label="Eliminar comparación de ${esc(r.card.name)}">×</button></div>`).join(''):'<p class="hint">Aún no tienes comparaciones guardadas. Busca una carta para empezar.</p>'}$('savedBtn').onclick=()=>{$('saved').hidden=false;renderSaved();$('saved').scrollIntoView({behavior:'smooth'})};$('closeSaved').onclick=()=>$('saved').hidden=true;$('savedList').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.open){const r=saved.find(x=>x.id===b.dataset.open);if(r)select(r.card,r)}if(b.dataset.delete){saved=saved.filter(x=>x.id!==b.dataset.delete);sync();renderSaved()}};
